// Types of the golden vectors generated by tools/NodaJs.Tools (data golden).
import type { EncodedValue } from "../scenarios/types.ts";

export interface FormattingGolden {
  /** Culture name ("" for invariant). */
  readonly culture: string;
  readonly cases: readonly FormattingCase[];
}

export interface FormattingCase {
  /** Value type, e.g. "LocalDate" (the pattern class is `${type}Pattern`). */
  readonly type: string;
  readonly pattern: string;
  readonly value: EncodedValue;
  /** NodaTime's formatted text (absent if formatting threw). */
  readonly text?: string;
  /** Whether NodaTime parses `text` back to `value`. */
  readonly roundTrips?: boolean;
  /** Exception type name, if NodaTime threw while formatting. */
  readonly error?: string;
}

export interface CompareGolden {
  readonly culture: string;
  /** [text, candidate, equal]: CompareInfo.Compare(text, candidate, CompareOptions.IgnoreCase) == 0. */
  readonly cases: readonly (readonly [string, string, boolean])[];
}

/** NodaTime.Serialization.SystemTextJson's output, one property per type, and the values it serialized. */
export interface JsonGolden {
  /** The calendar system ID (one file per calendar). */
  readonly calendar: string;
  readonly json: string;
  readonly properties: readonly JsonGoldenProperty[];
}

export interface JsonGoldenProperty {
  readonly name: string;
  /** The class whose fromJSON reads it, e.g. "ZonedDateTime". */
  readonly type: string;
  readonly value: EncodedValue;
}

/** A calendar's years from `minYear` to `maxYear`: `years[i]` indexes `yearTypes` for year `minYear + i`. */
export interface CalendarGolden {
  readonly id: string;
  readonly minYear: number;
  readonly maxYear: number;
  /** The start of `minYear`, in days since 1970-01-01 ISO. */
  readonly minDays: number;
  /** The end of `maxYear`, in days since 1970-01-01 ISO. */
  readonly maxDays: number;
  readonly yearTypes: readonly CalendarYearType[];
  readonly years: readonly number[];
}

export interface CalendarYearType {
  readonly leap: boolean;
  readonly days: number;
  /** `monthLengths[0]` is month 1. */
  readonly monthLengths: readonly number[];
  /** Days from the start of the year, by month number (not increasing for Hebrew scriptural). */
  readonly monthStarts: readonly number[];
}
